"""One-off: third trim of the longest skill descriptions. Run from the repo root.
Keeps the trigger situations and the skip pointers between neighbouring skills,
drops sentences that describe how the skill works (those live in the skill body)."""
import re

NEW = {
"security-hardening": "Locks down how a system is configured and run. Use for hardening a cloud account, servers, containers, networks, CI/CD pipelines and secrets, pen test or audit prep, fixing open ports or missing headers, MFA and least privilege, public buckets. Skip for reviewing application code (security-review), threat modelling a feature (security-prompter) and a live attack (incident-response).",
"devex-review": "Reviews and scores the developer experience of an API, SDK, CLI or docs by following the first-run path. Use for review our developer experience, time to first success, is onboarding good, getting started is slow, are error messages helpful, or before launching a developer-facing product. Skip for end-user interfaces (ui-polish, web-quality) and writing docs (documentation).",
"plan-challenge": "Reviews a plan before anything is built, challenging its premise, scope and completeness. Use for review my plan, is this worth building, think bigger or smaller, scope review, what am I missing. Skip for choosing between designs (design-decision), validating with several advisors (llm-council) and estimating time (estimation).",
"llm-council": "Validates a design, plan or solution with five advisors and a chairman, then checks the build against their findings. Use when the user asks for a council, advisors or several opinions, or to stress-test an approach that is costly to undo. Skip for small or reversible tasks (one agent is cheaper) and for running a whole build as a team (dev-orchestrator).",
"session-handoff": "Saves the working state of a task so a later session can continue where this one stopped, and restores it. Use for save my progress, hand this off, I am stopping for today, resume where I left off, where was I, or before the context fills up. Skip for long-term preferences (memory) and project documentation (documentation).",
"retro": "Runs a weekly or sprint engineering retrospective from git and pull request history. Use for weekly retro, what did we ship, sprint review, how did this week go, team velocity and health. Skip for incident postmortems (incident-response) and estimating future work (estimation).",
"dependency-audit": "Audits third-party dependencies for vulnerabilities, licence problems, abandoned packages and risky update habits. Use for npm audit noise, licence questions such as GPL in closed source, outdated packages, Dependabot or Renovate setup, SBOMs and whether a package is safe to add. Skip for upgrading one major framework (migrate-and-upgrade) and reviewing the project's own code (security-review).",
"data-ml-work": "Does machine learning and data analysis work you can trust. Use for training or evaluating a model, accuracy that looks too good, leakage, train and test splits, baselines, metrics, forecasting, A/B test readouts and analysing a dataset. Skip for plain app code (new-app-build), pipelines into a warehouse (data-engineering) and designing a user study (ux-research).",
"privacy-compliance": "Finds and fixes privacy and data-protection gaps. Use for GDPR, CCPA, HIPAA, COPPA, what personal data we store, consent and cookie banners, privacy policies, deleting or exporting a user's data, retention, data sent to vendors or AI providers, DPAs, breaches and children's data. Not legal advice. Skip for code vulnerabilities (security-review) and threat modelling a feature (security-prompter).",
"frontend-design": "Makes a user interface look deliberately designed instead of generic. Use before building or restyling any page, component or screen, for landing pages and dashboards, or when output looks like a default template. Starts from a design brief, then builds from tokens. Skip for backend work and tiny copy or colour tweaks.",
"migrate-and-upgrade": "Plans and runs migrations, large refactors and version upgrades safely. Use to move between libraries or frameworks, upgrade a language, framework or major dependency (for example Django 5 or Python 3.13), or restructure a whole codebase. Skip for a refactor inside one module or a few files (coding-discipline).",
"git-hygiene": "Keeps git history clean and recovers from git mistakes without losing work. Use for squashing or rewriting commits, rebase versus merge, undoing a commit or push, lost changes, a pushed secret or large file, force pushes and branching rules. Skip for deploy pipelines (release-engineering) and reviewing a change (change-review).",
"schema-changes": "Plans and runs database schema changes on live tables without downtime. Use for adding, renaming or dropping columns or tables, changing types, adding indexes, backfilling data and writing migrations when the app must stay up. Skip for local throwaway databases and rollout planning (release-engineering).",
"release-engineering": "Designs and runs safe releases and deployment pipelines. Use for setting up CI/CD, release processes, shipping to production, cutting a release, rollback, versioning, release notes, watching a deploy, or deploys that are manual, risky or have broken production. Skip for local-only scripts.",
"observability": "Makes a running system easy to understand and alert on, with logs, metrics, traces, dashboards and alerts. Use for adding logging or monitoring, finding out about problems from customers, noisy or missing alerts, SLOs, error budgets and tracing. Skip for debugging one known bug (bug-investigation) and a live outage (incident-response).",
"ui-polish": "Critiques and refines a built interface until it feels finished. Use when the user says polish this, it looks off, make it feel professional, review the UI or tidy the design, or after building any screen. Checks states, spacing, type, contrast, motion and responsive behaviour. Skip for non-visual code.",
"codebase-onboarding": "Learns an unfamiliar codebase quickly and writes a short verified CLAUDE.md. Use when the user just joined or inherited a repo, asks how a codebase works, where to start, how to run it, or to write a CLAUDE.md. Skip for changing a known codebase (coding-discipline) and designing something new (new-app-build).",
"coding-discipline": "Rules for any non-trivial code change, including bug fixes and any task that edits files. Use before and after editing code, when planning a multi-step task, or when a request is ambiguous. Also locks edits to one folder on request. Skip for one-line edits and plain questions.",
"mobile-ci": "Sets up build, test, signing and distribution pipelines for iOS and Android apps. Use for mobile CI/CD, Fastlane, EAS, Bitrise, certificates, provisioning profiles, keystores, TestFlight and Google Play uploads, build numbers, flaky emulator tests and macOS runner cost. Skip for web and server pipelines (release-engineering) and store policy or app design (mobile-app-work).",
"documentation": "Plans, audits and maintains a project's documentation. Use when docs are out of date or a mess, new people take too long to get started, deciding what docs a project needs, setting up a docs site (MkDocs, Docusaurus, Sphinx), API reference, runbooks, or keeping docs in sync with code. Skip for polishing one document's wording (plain-writing) and writing a repo's CLAUDE.md (codebase-onboarding).",
"data-engineering": "Builds and fixes data pipelines into a warehouse or lake so the numbers can be trusted. Use for ETL or ELT jobs, duplicates after a rerun, warehouse totals that do not match the source, backfills, incremental loads, late data and data quality checks (Airflow, dbt, Spark, BigQuery, Snowflake). Skip for training models (data-ml-work) and app database schema changes (schema-changes).",
"concise-answers": "Gives short, answer-first replies and keeps token use low. Use only when the user asks for a quick or short answer, tl;dr, be brief, save tokens or keep it cheap. Skip plain questions that were not asked to be short, and when the user wants depth or a full report.",
"llm-app-work": "Builds applications that call a language model (chatbots, RAG, agents with tools, extraction) so they are tested, safe and affordable. Use for adding an AI feature, prompts, structured output, embeddings, prompt injection, hallucinations, evaluating answers, token cost and model upgrades. Skip for training your own model (data-ml-work) and ordinary API design (api-design).",
"cloud-cost": "Finds why a cloud bill is high or jumped and cuts it safely. Use for rising AWS, Azure or GCP bills, idle or oversized resources, NAT and egress costs, savings plans or reserved instances, budgets and cost estimates. Skip for making code faster (performance-work) and writing the infrastructure code (infrastructure-as-code).",
"dev-lifecycle": "The entry point for building or changing software end to end. Use when the user asks to build, ship, fix, upgrade, migrate or rebuild something and it is unclear where to start, or says take this from idea to production, what is the process, or do this properly. Names the skill for each phase. Skip for small edits and questions.",
"test-strategy": "Decides what to test and writes tests that catch real bugs. Use for what should I test, write tests for this, flaky or slow tests, coverage, is this test any good, auditing a suite for low-value tests, or code about to change with weak tests. Skip when the only task is fixing one failing test (honest-fixes).",
}

before = after = 0
for name, desc in NEW.items():
    assert ': ' not in desc, name
    p = f'skills/{name}/SKILL.md'
    s = open(p, encoding='utf-8').read()
    old = re.search(r'^description:\s*(.*)$', s, re.M).group(1)
    s2, n = re.subn(r'^description:.*$', 'description: ' + desc.replace('\\', '\\\\'), s, count=1, flags=re.M)
    assert n == 1, name
    open(p, 'w', encoding='utf-8').write(s2)
    before += len(old); after += len(desc)
print('updated', len(NEW), 'chars', before, '->', after)
